"""Build seven-category external risk context. No operational impacts are asserted or applied."""
import json,hashlib
from datetime import datetime,timezone,date,timedelta
from pathlib import Path
R=Path(__file__).resolve().parents[1];O=R/'public_data/external_risk';O.mkdir(exist_ok=True)
def dump(name,obj): (O/name).write_text(json.dumps(obj,indent=2))
def jl(path,rows):path.write_text(''.join(json.dumps(x,ensure_ascii=False)+'\n' for x in rows))
now=datetime.now(timezone.utc).isoformat()
# Short authored paraphrases of reviewed primary sources; not copies of source bodies.
new=[
('NEWS_011','POLITICAL',['ECONOMIC'],'WTO','https://www.wto.org/english/news_e/news25_e/tfore_16apr25_e.htm','2025-04-16',None,None,2025,'Global','TRADE_POLICY_2025','WTO tariff-sensitive trade outlook','WTO lowered its 2025 merchandise-trade forecast in April, citing new tariffs and trade-policy uncertainty.','A dated forecast, not an observed demand decline or a tariff schedule. No blanket tariff rate or fictional product exposure can be inferred.','FORECAST'),
('NEWS_012','ECONOMIC',[],'World Bank','https://thedocs.worldbank.org/en/doc/1c533d236291c53757b147f8acb8a82f-0050012024/commodity-markets-outlook-october-2024',None,None,None,2024,'Global','COMMODITIES_OCT2024','Commodity market analysis source','The October 2024 report provides analysis of energy, metals and critical minerals, with commodity price forecasts.','Report context only; monthly observed prices have not been imported. Metadata publication date differs from the release date reported elsewhere, so exact availability is unverified. Forecasts are not actual procurement prices.','REPORT_CONTEXT'),
('NEWS_013','SOCIAL',[],'ILA and USMX joint statement','https://ilaunion.org/joint-statement-regarding-master-contract/','2024-10-03','2024-10-03',None,2024,'United States Atlantic and Gulf coast ports','ILA_USMX_2024','Labor action suspension','ILA and USMX announced a tentative wage agreement and suspension of current job actions, extending their contract for further negotiations.','Recovery notice, not evidence of a continuing strike. There are no US ocean routes in this fictional network, so direct operational exposure is not established.','RECOVERY_NOTICE'),
('NEWS_014','CULTURAL',['LEGAL'],'China State Council, reproduced by Haidian government','https://en.bjhd.gov.cn/workinginhaidian/supportingservices/publicholidays/202512/t20251211_4797062.shtml','2025-11-04','2026-02-15','2026-02-23',2026,'China','CN_SPRING_FESTIVAL_2026','Spring Festival calendar','The official schedule specifies Spring Festival leave from February 15–23, 2026, with February 14 and 28 designated as adjusted working days.','Government calendar; individual plant and supplier closure arrangements need confirmation. Do not infer absenteeism or output loss from cultural identity. Publication date is the original notice date; mirror posting may be later.','PLANNED_CALENDAR'),
('NEWS_015','TECHNOLOGICAL',[],'CrowdStrike','https://www.crowdstrike.com/en-us/blog/falcon-update-for-windows-hosts-technical-details/','2024-07-20','2024-07-19',None,2024,'Global; affected Windows hosts','FALCON_20240719','Software-update outage','CrowdStrike reported that its July 19 Windows sensor configuration update triggered crashes on affected hosts and identified the incident as unrelated to a cyberattack.','Update remediation time does not establish restoration time for every customer. The fictional company has no confirmed affected software inventory.','INCIDENT_REPORT'),
('NEWS_016','LEGAL',['POLITICAL','TECHNOLOGICAL'],'US Bureau of Industry and Security','https://www.bis.gov/press-release/commerce-strengthens-export-controls-restrict-chinas-capability-produce-advanced-semiconductors-military','2024-12-02',None,None,2024,'US jurisdiction; specified China-related transactions','BIS_ADVANCED_SEMICONDUCTORS_20241202','Advanced semiconductor export-control notice','BIS announced additional controls concerning semiconductor manufacturing equipment, software and high-bandwidth memory, alongside Entity List changes.','Historical announcement only. Applicability requires the actual rule, effective dates, item classification, origin, parties, end use and licenses. Ordinary automotive components are not automatically covered.','REGULATORY_ANNOUNCEMENT')]
p=R/'public_data/news/curated_evidence.jsonl';old=[json.loads(x) for x in p.read_text().splitlines()];byid={x['evidence_id']:x for x in old}
for x in old:
 if x['evidence_id'] in {f'NEWS_{i:03}' for i in range(1,11)}:
  x['primary_category']='POLITICAL' if x['evidence_id']=='NEWS_009' else 'ENVIRONMENTAL';x['secondary_categories']=[]
  x['impact_on_fictional_company']='UNVERIFIED';x['quantified_company_impact']=None
for id,cat,sec,pub,url,pdate,start,end,year,loc,cluster,title,claim,caveat,kind in new:
 prev=byid.get(id,{});retrieved=prev.get('retrieved_at_utc',now)
 byid[id]=dict(evidence_id=id,primary_category=cat,secondary_categories=sec,publisher=pub,source_url=url,published_date=pdate,published_at_utc=None,retrieved_at_utc=retrieved,available_at_utc=retrieved,event_start_date=start,event_end_date=end,event_year=year,event_date_precision='DAY' if start else 'UNKNOWN_OR_REPORT_PERIOD',location_text=loc,event_cluster_id=cluster,title_paraphrase=title,claim_summary=claim,caveat=caveat,source_kind=kind,acquisition_channel='CURATED_PRIMARY_SOURCE_NOT_GDELT',evidence_status='SOURCE_REVIEWED_ENTITY_IMPACT_UNVERIFIED',source_is_synthetic=False,linked_entity_ids=[],usage='HISTORICAL_REFERENCE_NOT_ASOF_VERIFIED',dedup_key=hashlib.sha256(url.encode()).hexdigest(),impact_on_fictional_company='UNVERIFIED',quantified_company_impact=None)
allrows=sorted(byid.values(),key=lambda x:x['evidence_id']);jl(p,allrows)
# Each pathway describes conditional consequences, not a causal claim about baseline records.
models=[
('POLITICAL',['conflict','sanctions announcement','border restriction','trade policy'],['NEWS_009','NEWS_011'],'route access or sourcing changes → longer transit or unavailable supply',['route/transit-country match','carrier notice','supplier site','effective time','contract coverage'],['shipment delay hours','unavailable material quantity','expediting cost'],'Route-specific additional transit and incremental transport cost; rerun inventory and order scheduling.',['route_legs','shipments','sourcing_agreements'],'Do not map a maritime event to an air/road shipment without a demonstrated dependency.'),
('ECONOMIC',['exchange rate change','commodity price change','inflation','demand contraction'],['NEWS_012','NEWS_011'],'input price, FX or demand change → landed-cost and margin change',['currency pair and date','observed commodity series','contract indexation','material cost share','order demand'],['landed cost delta INR','contribution margin delta INR','working capital delta INR'],'FX delta = foreign amount × (scenario INR-per-foreign-unit rate − baseline rate). Commodity pass-through = eligible cost × index change × contractual pass-through share.',['exchange_rates','purchase_order_lines','customer_order_lines'],'Do not replace synthetic constant FX with an unrelated market rate; forecasts remain separate from observations.'),
('SOCIAL',['strike','labor shortage','public health restrictions','local access protest'],['NEWS_013'],'confirmed workforce or access interruption → reduced throughput or delayed transport',['named affected site or route','start and suspension time','confirmed workforce availability','shift calendar'],['lost capacity hours','backlog units','recovery time hours'],'Lost hours = scheduled hours − available hours; recompute feasible production and delivery dates.',['line_capacity_daily','supplier_capacity_daily','route_legs'],'Use site evidence, not demographic proxies. The US strike example is a geographic/mode false-match test for this network.'),
('CULTURAL',['public holiday','festival calendar','planned shutdown'],['NEWS_014'],'confirmed holiday schedule → fewer available working days or shifted demand',['jurisdiction calendar','supplier confirmation','make-up working days','approved shifts','measured order change'],['available workdays','earliest feasible dispatch date','prebuild quantity'],'Apply confirmed site calendar overrides, including make-up days, then recalculate capacity and dispatch dates.',['plant_calendar','line_capacity_daily','supplier_capacity_daily'],'Culture is not an inherent risk. A public holiday does not prove closure or a demand surge. Existing baseline calendars currently use weekdays only.'),
('TECHNOLOGICAL',['software outage','cyber incident','equipment failure','component obsolescence'],['NEWS_015'],'confirmed system or machine dependency failure → processing or production interruption',['asset/software version','affected service dependency','incident window','site telemetry','verified restoration'],['system downtime hours','lost production units','processing delay hours'],'Intersect confirmed outage intervals with scheduled dependent operations; calculate capacity once per affected operation.',['production_lines','production_orders','shipment_updates'],'A vendor outage does not prove this company was affected. Asset/software dependency inventory is missing. Do not relabel an accidental outage as a cyberattack.'),
('ENVIRONMENTAL',['flood','typhoon','earthquake','heat','drought'],['NEWS_001','NEWS_005','NEWS_008'],'hazard plus physical exposure → site or route interruption',['event footprint','distance and station quality','site elevation/defenses','carrier or site status','event dates'],['route delay hours','unavailable capacity hours','stockout units'],'Use a confirmed operational delay or explicitly simulated assumption, then recompute material availability; weather alone does not set damage duration.',['plants','supplier_sites','route_legs','shipments'],'Do not infer exact plant damage from a nearby weather station, or add repeated reports as independent events.'),
('LEGAL',['export control','customs rule','product compliance','binding sanction'],['NEWS_016'],'applicable rule or missing authorization → blocked sourcing or clearance delay',['jurisdiction','HS/ECCN classification','origin','legal entity identity','end use','rule effective dates','license status'],['blocked order quantity','clearance delay hours','compliant sourcing options'],'Filter candidates by a separately verified compliance decision. Calculate disruption costs only after item and transaction applicability is established.',['materials','suppliers','sourcing_agreements','purchase_order_lines'],'Never declare a fictional supplier sanctioned or a component controlled from country alone. Agent output is a review flag; no autonomous legal clearance.')]
pathways=[]
for cat,signals,eids,chain,inputs,outputs,formula,tables,guard in models:
 pathways.append(dict(pathway_id='PATH_'+cat,category=cat,signal_types=signals,example_evidence_ids=eids,conditional_impact_chain=chain,required_exposure_inputs=inputs,impact_metrics=outputs,calculation_guidance=formula,relevant_operational_tables=tables,guardrail=guard,status='DESIGN_NOT_EXECUTED',impact_is_inference=True))
jl(O/'impact_pathways.jsonl',pathways)
registry=[]
for x in allrows:
 registry.append({'source_id':'SRC_'+x['evidence_id'],'category':x['primary_category'],'secondary_categories':x['secondary_categories'],'publisher':x['publisher'],'url':x['source_url'],'evidence_id':x['evidence_id'],'ingestion_status':'SHORT_REVIEWED_PARAPHRASE_INCLUDED','full_text_stored':False})
registry += [dict(source_id='SRC_WB_SERIES',category='ECONOMIC',publisher='World Bank',url='https://datacatalog.worldbank.org/search/dataset/0038238/commodity-prices-history-and-projections',ingestion_status='CATALOG_REVIEWED_TIME_SERIES_NOT_IMPORTED',intended_fields=['commodity','month','price','unit','actual_or_forecast','vintage']),dict(source_id='SRC_UNCTAD',category='POLITICAL',publisher='UNCTAD',url='https://unctad.org/publication/navigating-troubled-waters-impact-global-trade-disruption-shipping-routes-red-sea-black',ingestion_status='DISCOVERED_SEARCH_METADATA_ONLY_FULL_PAGE_RETURNED_403',intended_fields=['route','disruption mechanism','report date']),dict(source_id='SRC_NOAA',category='ENVIRONMENTAL',publisher='NOAA NCEI',url='https://www.ncei.noaa.gov/data/global-summary-of-the-day/access/',ingestion_status='PARTIAL_STATION_DATA_IMPORTED_SEE_WEATHER_COVERAGE')]
dump('source_registry.json',registry)
# Calendar facts extracted from one notice; site implementation remains unconfirmed.
calendar=[]
for i in range(9):
 d=date(2026,2,15)+timedelta(days=i);calendar.append({'date':str(d),'jurisdiction':'CN','calendar_type':'PUBLIC_HOLIDAY','name':'Spring Festival','source_evidence_id':'NEWS_014','site_closure_confirmed':False})
for day in ['2026-02-14','2026-02-28']:calendar.append({'date':day,'jurisdiction':'CN','calendar_type':'ADJUSTED_WORKDAY','name':'Spring Festival make-up working day','source_evidence_id':'NEWS_014','site_closure_confirmed':False})
jl(O/'calendar_reference.jsonl',calendar)
dump('event_schema.json',{'categories':[m[0] for m in models],'classification':'One primary category plus optional secondary categories. Shared event_cluster_id prevents double counting.','impact_record_fields':{'event_id':'string','evidence_ids':'list[string]','entity_id':'string','exposure_status':'UNASSESSED | UNRELATED | POSSIBLE | CONFIRMED | SIMULATED','association_basis':'specific site/route/item/system match','effective_start_utc':'nullable timestamp','effective_end_utc':'nullable timestamp','known_at_utc':'timestamp','metric':'string','unit':'string','baseline_value':'nullable number','scenario_value':'nullable number','delta':'nullable number','assumption_ids':'list[string]','calculation_version':'string','review_status':'PENDING | APPROVED | REJECTED'},'rule':'Do not emit a numerical company-impact claim until exposure and calculation inputs exist.'})
dump('validation.json',{'passed':set(x['primary_category'] for x in allrows)==set(x[0] for x in models) and all(e in byid for x in pathways for e in x['example_evidence_ids']) and len({x['source_url'] for x in allrows})==len(allrows),'categories':7,'total_evidence_records':len(allrows),'new_evidence_records':6,'impact_pathways':7,'calendar_reference_days':11,'source_registry_entries':len(registry),'applied_operational_impacts':0})
print((O/'validation.json').read_text())
